    wire [4:0] bi31 = (z31 > bv30) ? 5'd31 : bi30;

    function [H_BITS-1:0] requant(input signed [ACC_W-1:0] a);
        reg signed [ACC_W-1:0] r;
        begin
            r = (a + (1 <<< (S1 - 1))) >>> S1;
            if (a <= 0)                       requant = 0;
            else if (r > (1 << H_BITS) - 1)   requant = (1 << H_BITS) - 1;
            else                              requant = r[H_BITS-1:0];
        end
    endfunction

    always @(posedge clk) begin
        if (!rst_n) begin
            ctx       <= 0;
            lfsr      <= 16'hACE1;
            busy      <= 1'b0;
            done      <= 1'b0;
            token_out <= 5'd0;
        end else begin
            done <= 1'b0;
            if (start) begin
                token_out <= bi31;
                ctx       <= {bi31, ctx[N*5-1:5]};
                lfsr      <= lf32;
                done      <= 1'b1;
            end else if (push) begin
                ctx <= {token_in, ctx[N*5-1:5]};
            end
        end
    end
endmodule
